import React, { useState } from "react";
import { useParams } from "react-router-dom";

const VideoPage = () => {
  const { id } = useParams();

  const [currentModule, setCurrentModule] = useState({
    title: "01 - Bem Vindo ao Curso",
    file: "",
  });

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col items-center p-8">
      {/* Título */}
      <h1 className="text-4xl font-bold text-gray-800 text-center mb-10 tracking-tight">
        Formação em Liderança
      </h1>

      <div className="flex w-full max-w-7xl bg-white rounded-xl shadow-lg overflow-hidden">
        {/* Sidebar - Módulos */}
        <aside className="w-72 bg-red-600 text-white flex flex-col justify-between">
          <div className="p-6">
            <h2 className="text-2xl font-extrabold mb-6 uppercase">Módulos</h2>
            <ul className="space-y-4">
              {[
                "Aula 01 - Bem Vindo",
                "Aula 02 - Liderança",
                "Aula 03 - Desenvolvimento",
                "Aula 04 - Propósito",
                "Aula 05 - Estilos",
                "Aula 06 - Bônus",
              ].map((mod, idx) => (
                <li
                  key={idx}
                  className={`flex items-center gap-2 cursor-pointer transition ${
                    currentModule.title.includes(mod)
                      ? "font-bold text-white"
                      : "opacity-90 hover:opacity-100"
                  }`}
                  onClick={() => setCurrentModule({ title: mod, file: "" })}
                >
                  <span className="text-lg">✔️</span>
                  <span>{mod}</span>
                </li>
              ))}
            </ul>
          </div>

          {/* Botão Material de Apoio */}
          <div className="p-6">
            <button className="w-full bg-white text-red-600 font-semibold py-3 px-4 rounded-lg shadow hover:bg-gray-100 transition text-center">
              Material de Apoio
            </button>
          </div>
        </aside>

        {/* Player */}
        <main className="flex-1 p-8 flex flex-col">
          <div className="relative mb-6">
            <video
              className="w-full h-[480px] rounded-lg shadow-lg bg-black"
              controls
            >
              <source src={currentModule.file} type="video/mp4" />
              Seu navegador não suporta vídeo.
            </video>
          </div>

          {/* Descrição do módulo */}
          <div className="p-6 bg-gray-100 rounded-lg shadow-inner">
            <p className="text-xl font-semibold text-gray-800">
              {currentModule.title}
            </p>
            <p className="text-sm text-gray-500 mt-1">Duração: --</p>
          </div>
        </main>
      </div>
    </div>
  );
};

export default VideoPage;
